// src/components/AuthProvider.js
import React, { createContext, useContext, useState } from 'react';
import axios from 'axios'; // Import axios if you'll use it for API requests

const AuthContext = createContext();

export function useAuth() {
  return useContext(AuthContext);
}

export default function AuthProvider({ children }) {
  const [user, setUser] = useState(null);

  const register = async (email, password) => {
    try {
      // Replace with your API registration endpoint
      const response = await axios.post(`${process.env.REACT_APP_API_URL}/auth/register`, { email, password });
      if (response.status === 201) {
        console.log('Registration successful:', response.data);
        // Optionally, auto-login after successful registration
      }
    } catch (error) {
      console.error('Registration error:', error);
      throw new Error('Registration failed');
    }
  };

  const login = async (email, password) => {
    try {
      // Replace with your API login endpoint
      const response = await axios.post(`${process.env.REACT_APP_API_URL}/auth/login`, { email, password });
      if (response.status === 200) {
        const { token } = response.data;
        localStorage.setItem('token', token); // Save token to localStorage
        setUser({ email }); // Set user info
      }
    } catch (error) {
      console.error('Login error:', error);
      throw new Error('Login failed');
    }
  };

  const logout = () => {
    localStorage.removeItem('token'); // Remove token from localStorage
    setUser(null);
  };

  return (
    <AuthContext.Provider value={{ user, register, login, logout }}>
      {children}
    </AuthContext.Provider>
  );
}
